71	function pad(value) {
72	  return value < 10 ? "0" + value : "" + value
73	}
74	
75	var CITY_STORAGE_KEY = "infoWeatherCity"
76	
77	export default {
78	  private: {
79	    isDark: false,
80	    themeButtonText: "深色模式",
81	    modeLabel: "浅色",
82	    currentTime: "--:--",
83	    currentDate: "",
84	    weatherSummary: "获取天气中...",
85	    newsTitle: "正在加载新闻...",
86	    newsSource: "",
87	    newsUrl: "",
88	    newsDesc: "",
89	    historyList: []
90	  },
91	
92	  onInit() {
93	    this.isDark = getThemeSync()
94	    this.themeButtonText = this.isDark ? "浅色模式" : "深色模式"
95	    this.modeLabel = this.isDark ? "深色" : "浅色"
96	    this.updateClock()
97	    this.updateDate()
98	  },
99	
100	  onShow() {
101	    this.updateClock()
102	    this.updateDate()
103	    // 串行调用，避免并发 fetch 导致框架崩溃
104	    this.loadWeather()
105	  },
106	
107	  onDestroy() {
108	  },
109	
110	  updateClock() {
111	    var now = new Date()
112	    this.currentTime = pad(now.getHours()) + ":" + pad(now.getMinutes())
113	  },
114	
115	  updateDate() {
116	    var now = new Date()
117	    var weekDays = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"]
118	    this.currentDate = now.getFullYear() + "年" + (now.getMonth() + 1) + "月" + now.getDate() + "日 " + weekDays[now.getDay()]
119	  },
120	
121	  toggleTheme() {
122	    this.isDark = !this.isDark
123	    this.themeButtonText = this.isDark ? "浅色模式" : "深色模式"
124	    this.modeLabel = this.isDark ? "深色" : "浅色"
125	    setTheme(this.isDark)
126	  },
127	
128	  goNews() {
129	    router.push({ uri: "pages/news" })
130	  },
131	
132	  goWeather() {
133	    router.push({ uri: "pages/weather" })
134	  },
135	
136	  goExpress() {
137	    router.push({ uri: "pages/express" })
138	  },
139	
140	  showNewsDetail() {
141	    if (!this.newsTitle || this.newsTitle === "正在加载新闻...") return
142	    router.push({
143	      uri: "pages/detail",
144	      params: {
145	        title: this.newsTitle,
146	        description: this.newsDesc,
147	        source: this.newsSource,
148	        url: this.newsUrl,
149	        isDark: this.isDark
150	      }
151	    })
152	  },
153	
154	  loadWeather() {
155	    var self = this
156	    storage.get({
157	      key: CITY_STORAGE_KEY,
158	      success: function (data) {
159	        var city = data || "北京"
160	        self.fetchWeather(city)
161	      },
162	      fail: function () {
163	        self.fetchWeather("北京")
164	      }
165	    })
166	  },
167	
168	  fetchWeather(city) {
169	    var self = this
170	    self.weatherSummary = city + " 获取天气中..."
171	    getWeather(city).then(function (info) {
172	      self.weatherSummary = info.title + " " + info.message + " " + info.subtitle
173	      // 天气加载完后，加载新闻
174	      self.loadNews()
175	    }).catch(function () {
176	      self.weatherSummary = city + " 天气获取失败"
177	      // 失败也要继续加载新闻
178	      self.loadNews()
179	    })
180	  },
181	
182	  loadNews() {
183	    var self = this
184	    getLatestNews({ categories: ["politics"], pageSize: 20 }).then(function (list) {
185	      if (list && list.length) {
186	        self.newsTitle = list[0].title
187	        self.newsSource = list[0].source + " · " + list[0].published
188	        self.newsUrl = list[0].url
189	        self.newsDesc = list[0].description
190	      }
191	      // 新闻加载完后，加载历史
192	      self.loadHistory()
193	    }).catch(function () {
194	      self.newsTitle = "新闻获取失败"
195	      // 失败也要继续加载历史
196	      self.loadHistory()
197	    })
198	  },
199	
200	  formatHistoryYear(year) {
201	    var y = parseInt(year, 10)
202	    if (isNaN(y)) return year + "年"
203	    if (y < 0) return "公元前" + Math.abs(y) + "年"
204	    return y + "年"
205	  },
206	
207	  loadHistory() {
208	    var self = this
209	    getTodayInHistory().then(function (list) {
210	      if (list && list.length) {
211	        var formatted = list.map(function (item) {
212	          return { title: item.title, year: item.year, yearLabel: self.formatHistoryYear(item.year), desc: item.desc, link: item.link }
213	        })
214	        self.historyList = formatted
215	      }
216	    }).catch(function () {
217	      // 历史加载失败，静默处理
218	    })
219	  }
220	}
221	</script>
