43	/**
44	 * 网络请求 - 直接调用 fetch，避免 Promise 链嵌套导致框架回调丢失
45	 */
46	function request(options) {
47	  var url = options.url
48	  var method = options.method || "GET"
49	  var responseType = options.responseType || "json"
50	
51	  console.log("request: " + method + " " + url)
52	  return fetch.fetch({
53	    url: url,
54	    method: method,
55	    header: options.header || {},
56	    responseType: responseType
57	  }).then(function (res) {
58	    console.log("request success: code=" + (res.code || res.statusCode) + ", url=" + url)
59	
60	    var code = res.code || res.statusCode
61	    var data = res.data !== undefined ? res.data : res.result
62	
63	    if (typeof data === "string") {
64	      data = parseData(data)
65	    }
66	
67	    if (code >= 200 && code < 300) {
68	      return data
69	    } else if (data && typeof data === "object" && Object.keys(data).length > 0) {
70	      return data
71	    } else {
72	      throw new Error("HTTP " + code)
73	    }
74	  })
75	}
