80	export function getWeather(city) {
81	  var query = encodeQuery({
82	    city: city,
83	    extended: true,
84	    forecast: true,
85	    indices: true
86	  })
87	
88	  return request({
89	    url: PROVIDERS.weather.url + "?" + query
90	  }).then(function (data) {
91	    if (!data || !data.city) {
92	      return {
93	        ready: false,
94	        title: city,
95	        subtitle: "查询失败",
96	        message: "天气数据暂不可用",
97	        details: [],
98	        detailsExtra: [],
99	        indexes: [],
100	        forecasts: [],
101	        alerts: []
102	      }
103	    }
104	
105	    var temp = data.temperature !== undefined ? data.temperature : "--"
106	    var desc = data.weather || "未知"
107	    var feelsLike = data.feels_like !== undefined ? data.feels_like : "--"
108	    var humidity = data.humidity !== undefined ? data.humidity + "%" : "--"
109	    var windDir = data.wind_direction || "--"
110	    var windPower = data.wind_power || "--"
111	    var clouds = data.cloud !== undefined ? data.cloud + "%" : "--"
112	    var vis = data.visibility !== undefined ? data.visibility + "km" : "--"
113	    var pressure = data.pressure !== undefined ? data.pressure + "hPa" : "--"
114	    var district = data.city || city
115	    var aqi = data.aqi || 0
116	    var pm25 = data.air_pollutants ? data.air_pollutants.pm25 : 0
117	    var pm10 = data.air_pollutants ? data.air_pollutants.pm10 : 0
118	
119	    // 生活指数
120	    var indexes = []
121	    if (data.life_indices) {
122	      var indices = data.life_indices
123	      var indexNames = {
124	        "clothing": "穿衣", "uv": "紫外线", "car_wash": "洗车",
125	        "drying": "晾晒", "air_conditioner": "空调", "cold_risk": "感冒",
126	        "exercise": "运动", "comfort": "舒适度", "travel": "出行",
127	        "fishing": "钓鱼", "allergy": "过敏", "sunscreen": "防晒",
128	        "mood": "心情", "beer": "啤酒", "umbrella": "雨伞",
129	        "traffic": "交通", "air_purifier": "空气净化器", "pollen": "花粉"
130	      }
