144	    if (data.forecast) {
145	      for (var i = 0; i < data.forecast.length && i < 7; i++) {
146	        var f = data.forecast[i]
147	        forecasts.push({
148	          day: f.week || "--",
149	          info: (f.weather_day || "--") + "/" + (f.weather_night || "--") + " " + (f.temp_min || "--") + "~" + (f.temp_max || "--") + "°C"
150	        })
151	      }
152	    }
153	
154	    // 预警
155	    var alerts = []
156	    if (data.alerts) {
157	      for (var j = 0; j < data.alerts.length; j++) {
158	        var alert = data.alerts[j]
159	        alerts.push({
160	          title: alert.type + alert.level + " 正在生效",
161	          alertTitle: alert.title || "",
162	          desc: alert.text || ""
163	        })
164	      }
165	    }
166	
167	    return {
168	      ready: true,
169	      title: district,
170	      subtitle: desc,
171	      message: temp + "°C",
172	      details: [
