195	/**
196	 * 获取新闻（Promise 写法）
197	 */
198	export function getLatestNews(options) {
199	  var params = options || {}
200	  var categories = params.categories && params.categories.length ? params.categories.join(",") : ""
201	
202	  var query = encodeQuery({
203	    language: "zh",
204	    country: "CN",
205	    category: categories,
206	    page_size: params.pageSize || 20,
207	    apiKey: CURRENTS_API_KEY.trim()
208	  })
209	
210	  return request({
211	    url: CURRENTS_BASE_URL + "/latest-news?" + query
212	  }).then(function (data) {
213	    if (!data || data.status !== "ok" || !data.news) {
214	      return []
215	    }
216	    var filtered = data.news
217	      .map(function (item) {
218	        if (!item) return null
219	        var source = item.author || "未知来源"
220	        var title = item.title || "未命名新闻"
221	        var desc = item.description || "暂无摘要"
222	        return {
223	          id: item.id || "",
224	          title: title,
225	          description: desc,
226	          source: source,
227	          url: item.url || "",
228	          published: item.published || ""
229	        }
230	      })
231	      .filter(function (item) {
232	        return item && item.description && item.description !== item.title
233	      })
234	    return filtered
235	  })
236	}
