238	/**
239	 * 获取历史上的今天（Promise 写法）
240	 */
241	export function getTodayInHistory() {
242	  return request({
243	    url: "https://tmini.net/api/today?type=json"
244	  }).then(function (data) {
245	    if (!data || data.code !== 200 || !data.events) {
246	      return []
247	    }
248	    var result = data.events.slice(0, 5).map(function (item) {
249	      return {
250	        title: item.title || "",
251	        year: item.year || "",
252	        desc: item.desc || "",
253	        link: item.link || ""
254	      }
255	    })
256	    return result
257	  })
258	}
