260	/**
261	 * 获取快递信息（Promise 写法）
262	 */
263	export function getExpress(trackingNo) {
264	  var provider = PROVIDERS.express
265	  if (!trackingNo) {
266	    return Promise.resolve({
267	      ready: false,
268	      title: "请输入运单号",
269	      subtitle: provider.name,
270	      details: ["支持主流快递公司", "输入运单号后点击查询按钮"]
271	    })
272	  }
273	
274	  var query = encodeQuery({
275	    tracking_number: trackingNo
276	  })
277	
278	  return request({
279	    url: provider.url + "?" + query
280	  }).then(function (data) {
281	    if (data && data.tracking_number) {
282	      var tracks = data.tracks || []
283	      var carrierName = data.carrier_name || "快递公司"
284	      var statusText = data.status || ""
285	
286	      return {
287	        ready: true,
288	        title: data.tracking_number || trackingNo,
289	        subtitle: carrierName,
290	        status: statusText,
291	        details: tracks.map(function (item, index) {
292	          return {
293	            time: item.time || "",
294	            text: item.context || "",
295	            isLatest: index === 0
296	          }
297	        })
298	      }
299	    } else {
300	      return {
301	        ready: false,
302	        title: trackingNo,
303	        subtitle: "查询失败",
304	        status: "",
305	        details: []
306	      }
307	    }
308	  }).catch(function (err) {
309	    return {
310	      ready: false,
311	      title: trackingNo,
312	      subtitle: "查询出错",
313	      status: "",
314	      details: []
315	    }
316	  })
317	}
