137	import { getThemeSync, setTheme } from "../../common/theme"
138	
139	function pad(value) {
140	  return value < 10 ? "0" + value : "" + value
141	}
142	
143	export default {
144	  private: {
145	    isDark: false,
146	    themeButtonText: "深色模式",
147	    modeLabel: "浅色",
148	    currentTime: "--:--",
149	    trackingNo: "",
150	    expressLoading: false,
151	    expressStateText: "",
152	    hasError: false,
153	    errorText: "",
154	    showKeyboard: false,
155	    isNumberKeyboard: true,
156	    savedList: [],
157	    expressInfo: {
158	      title: "请输入运单号",
159	      subtitle: "UApiPro-快递查询",
160	      status: "",
161	      details: []
162	    }
163	  },
164	
165	  onInit() {
166	    this.isDark = getThemeSync()
167	    this.themeButtonText = this.isDark ? "浅色模式" : "深色模式"
168	    this.modeLabel = this.isDark ? "深色" : "浅色"
169	    this.updateClock()
170	    this.loadSavedList()
171	  },
172	
173	  onShow() {
174	    this.updateClock()
175	    // 订阅物理按键导航
176	    
177	  },
178	
179	  onDestroy() {
180	    // 取消导航订阅
181	    
182	  },
183	
184	  updateClock() {
185	    var now = new Date()
186	    this.currentTime = pad(now.getHours()) + ":" + pad(now.getMinutes())
187	  },
188	
189	  toggleTheme() {
190	    this.isDark = !this.isDark
191	    this.themeButtonText = this.isDark ? "浅色模式" : "深色模式"
192	    this.modeLabel = this.isDark ? "深色" : "浅色"
193	    setTheme(this.isDark)
194	  },
195	
196	  goHome() {
197	    router.push({ uri: "pages/index" })
198	  },
199	
200	  goNews() {
201	    router.back()
202	  },
203	
204	  goWeather() {
205	    router.push({ uri: "pages/weather" })
206	  },
207	
208	  toggleKeyboard() {
209	    this.showKeyboard = !this.showKeyboard
210	  },
211	
212	  switchKeyboard() {
213	    this.isNumberKeyboard = !this.isNumberKeyboard
214	  },
215	
216	  onKeyTap(key) {
217	    if (key === "DEL") {
218	      if (this.trackingNo.length > 0) {
219	        this.trackingNo = this.trackingNo.substring(0, this.trackingNo.length - 1)
220	      }
221	    } else if (key === "CLR") {
222	      this.trackingNo = ""
223	    } else if (key === "OK") {
224	      this.showKeyboard = false
225	    } else {
226	      this.trackingNo += key
227	    }
228	  },
229	
230	  queryExpress() {
231	    var trackingNo = this.trackingNo.trim()
232	    if (!trackingNo) {
233	      this.expressInfo = {
234	        title: "请输入运单号",
235	        subtitle: "UApiPro-快递查询",
236	        status: "",
237	        details: []
238	      }
239	      return
240	    }
241	
242	    this.showKeyboard = false
243	    this.expressLoading = true
244	    this.expressStateText = "正在查询快递信息"
245	
246	    var self = this
247	    getExpress(trackingNo).then(function (info) {
248	      self.expressInfo = info
249	      self.expressLoading = false
250	      self.saveToList(trackingNo)
251	    }).catch(function (err) {
252	      self.expressLoading = false
253	      self.hasError = true
254	      self.errorText = "快递查询失败"
255	    })
256	  },
257	
258	  loadSavedList() {
259	    this.savedList = []
260	  },
261	
262	  saveToList(trackingNo) {
263	    if (!trackingNo) return
264	    var list = this.savedList.filter(function (item) { return item !== trackingNo })
265	    list.unshift(trackingNo)
266	    if (list.length > 10) list = list.slice(0, 10)
267	    this.savedList = list
268	  },
269	
270	  removeSaved(index) {
271	    var list = this.savedList.filter(function (_, i) { return i !== index })
272	    this.savedList = list
273	  },
274	
275	  loadSaved(item) {
276	    this.trackingNo = item
277	    this.queryExpress()
278	  }
279	}
280	</script>
