import fetch from "@system.fetch"

const CURRENTS_API_KEY = "I_gqH5IB0yC8eS7mhIVx7LmQkx2IpDOtmCI6WTsksar1EFbA"
const CURRENTS_BASE_URL = "https://api.currentsapi.services/v1"

const PROVIDERS = {
